const SCHEMA_SQL = "-- MaterialFlow schema\n\nCREATE TABLE IF NOT EXISTS customers (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  phone TEXT,\n  email TEXT,\n  billing_address TEXT,\n  notes TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS drivers (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  phone TEXT,\n  truck_label TEXT,\n  pin TEXT NOT NULL,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS materials (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  unit TEXT NOT NULL DEFAULT 'yard',\n  default_price REAL NOT NULL DEFAULT 0,\n  active INTEGER NOT NULL DEFAULT 1\n);\n\nCREATE TABLE IF NOT EXISTS settings (\n  key TEXT PRIMARY KEY,\n  value TEXT\n);\n\nCREATE TABLE IF NOT EXISTS mileage_bands (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  min_miles REAL NOT NULL,\n  max_miles REAL,\n  fee REAL,\n  label TEXT,\n  sort_order INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS sms_recipients (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  phone TEXT NOT NULL,\n  carrier TEXT NOT NULL DEFAULT 'verizon',\n  custom_gateway_domain TEXT,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS orders (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  order_number TEXT NOT NULL UNIQUE,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  material_id INTEGER NOT NULL REFERENCES materials(id),\n  quantity REAL NOT NULL,\n  unit TEXT NOT NULL,\n  price_per_unit REAL NOT NULL DEFAULT 0,\n  delivery_address TEXT NOT NULL,\n  distance_miles REAL,\n  delivery_fee REAL NOT NULL DEFAULT 0,\n  sales_tax_rate REAL NOT NULL DEFAULT 0,\n  sales_tax_amount REAL NOT NULL DEFAULT 0,\n  total_amount REAL NOT NULL DEFAULT 0,\n  square_invoice_number TEXT,\n  square_invoiced INTEGER NOT NULL DEFAULT 0,\n  square_paid INTEGER NOT NULL DEFAULT 0,\n  requested_date TEXT,\n  requested_window TEXT,\n  notes TEXT,\n  status TEXT NOT NULL DEFAULT 'new', -- new, scheduled, out_for_delivery, delivered, invoiced, cancelled\n  driver_id INTEGER REFERENCES drivers(id),\n  scheduled_date TEXT,\n  scheduled_time TEXT,\n  delivered_at TEXT,\n  driver_notes TEXT,\n  invoice_id INTEGER,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS invoices (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  invoice_number TEXT NOT NULL UNIQUE,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  status TEXT NOT NULL DEFAULT 'draft', -- draft, sent, paid, partial, void\n  subtotal REAL NOT NULL DEFAULT 0,\n  tax_rate REAL NOT NULL DEFAULT 0,\n  tax_amount REAL NOT NULL DEFAULT 0,\n  total REAL NOT NULL DEFAULT 0,\n  amount_paid REAL NOT NULL DEFAULT 0,\n  issued_date TEXT,\n  due_date TEXT,\n  paid_date TEXT,\n  notes TEXT,\n  pay_token TEXT UNIQUE,\n  stripe_checkout_url TEXT,\n  stripe_session_id TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS invoice_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  invoice_id INTEGER NOT NULL REFERENCES invoices(id),\n  order_id INTEGER REFERENCES orders(id),\n  description TEXT NOT NULL,\n  quantity REAL NOT NULL,\n  unit TEXT,\n  unit_price REAL NOT NULL,\n  amount REAL NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS payments (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  invoice_id INTEGER NOT NULL REFERENCES invoices(id),\n  amount REAL NOT NULL,\n  method TEXT NOT NULL, -- stripe, cash, check, ach, other\n  reference TEXT,\n  paid_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS deliveries (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  sequence INTEGER NOT NULL DEFAULT 1,\n  quantity REAL NOT NULL,\n  driver_id INTEGER REFERENCES drivers(id),\n  scheduled_date TEXT,\n  slot_index INTEGER,\n  status TEXT NOT NULL DEFAULT 'unscheduled', -- unscheduled, scheduled, delivered, cancelled\n  delivered_at TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);\nCREATE INDEX IF NOT EXISTS idx_orders_driver_date ON orders(driver_id, scheduled_date);\nCREATE INDEX IF NOT EXISTS idx_invoices_customer ON invoices(customer_id);\nCREATE INDEX IF NOT EXISTS idx_deliveries_order ON deliveries(order_id);\nCREATE INDEX IF NOT EXISTS idx_deliveries_driver_date ON deliveries(driver_id, scheduled_date);\n";

// DATA_DIR points at a persistent volume mount in production (e.g. Railway) so
// the database survives redeploys. Falls back to the app directory otherwise
// (fine for local runs, but ephemeral on most hosts without a volume).
const DATA_DIR = process.env.DATA_DIR || __dirname;
const DB_PATH = path.join(DATA_DIR, 'materialflow.db');
const db = new DatabaseSync(DB_PATH);
db.exec('PRAGMA foreign_keys = ON;');
db.exec(SCHEMA_SQL);

// Lightweight migrations: CREATE TABLE IF NOT EXISTS above does nothing for a
// table that already exists, so any new column added to the schema after a
// database was first created needs an explicit ADD COLUMN here (guarded so
// it's a no-op once applied). This keeps existing data intact across deploys.
function ensureColumn(table, column, definition) {
  const cols = db.prepare(`PRAGMA table_info(${table})`).all();
  if (!cols.some((c) => c.name === column)) db.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`);
}
(function migrate() {
  ensureColumn('orders', 'distance_miles', 'REAL');
  ensureColumn('orders', 'delivery_fee', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('orders', 'square_invoice_number', 'TEXT');
  ensureColumn('orders', 'square_invoiced', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('orders', 'square_paid', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('sms_recipients', 'carrier', "TEXT NOT NULL DEFAULT 'verizon'");
  ensureColumn('sms_recipients', 'custom_gateway_domain', 'TEXT');
  ensureColumn('orders', 'sales_tax_rate', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('orders', 'sales_tax_amount', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('orders', 'total_amount', 'REAL NOT NULL DEFAULT 0');
})();

function run(sql, params = []) { return db.prepare(sql).run(...params); }
function get(sql, params = []) { return db.prepare(sql).get(...params); }
function all(sql, params = []) { return db.prepare(sql).all(...params); }

function getSetting(key, fallback = null) {
  const row = get('SELECT value FROM settings WHERE key = ?', [key]);
  return row && row.value !== '' && row.value !== null ? row.value : fallback;
}
function setSetting(key, value) {
  const existing = get('SELECT key FROM settings WHERE key = ?', [key]);
  if (existing) run('UPDATE settings SET value = ? WHERE key = ?', [value, key]);
  else run('INSERT INTO settings (key, value) VALUES (?, ?)', [key, value]);
}

